// Generated by Cypress Author on 2026-10-22
//
// INV 06 (P0) — Plano_de_Testes_QA_MatchWallet.md §10 (docs-test/areas/inv.md).
// Não existe fluxo de equipe para vincular carteira: o vínculo nasce de `POST /suitability/avaliar`
// (fecha o vínculo aberto e cria outro). Por isso o "fluxo autorizado" aqui é a reavaliação, e as
// datas "conhecidas" são só a ordem dos eventos. Contas DESCARTÁVEIS.
//
// ATENÇÃO — o segundo teste deve FALHAR enquanto `/suitability/avaliar` for `@Public()` e confiar
// no `usuarioId` do corpo: qualquer cliente (ou visitante) reescreve o vínculo de outra pessoa.

const NAO_SUCESSO = [400, 401, 403, 404, 405, 422]

function vinculoAtual() {
  return cy
    .apiRequest<{ carteiraVinculada: { id: string } | null }>({
      method: 'GET',
      url: '/auth/me',
    })
    .its('body.carteiraVinculada.id')
}

describe('Plano QA · Gestão do vínculo com a carteira', () => {
  it('INV 06 · reavaliação troca A por B → vínculo coerente na conta e no dashboard, cliente não altera por outros caminhos', () => {
    cy.criarUsuarioDescartavel().then((conta) => {
      cy.loginComo(conta)

      cy.avaliarSuitability(conta, 'menor').then((primeira) => {
        const carteiraA = primeira.carteiraRecomendada
        expect(carteiraA, 'carteira A').not.to.eq(null)
        vinculoAtual().should('eq', carteiraA?.id)

        cy.avaliarSuitability(conta, 'maior').then((segunda) => {
          const carteiraB = segunda.carteiraRecomendada
          expect(carteiraB, 'carteira B').not.to.eq(null)
          expect(carteiraB?.id, 'A e B precisam ser carteiras diferentes').not.to.eq(carteiraA?.id)

          // Troca refletida na conta e no painel (mesma fonte de verdade).
          vinculoAtual().should('eq', carteiraB?.id)
          cy.apiRequest<{ carteira: { id: string } | null }>({
            method: 'GET',
            url: '/dashboard/investidor',
          })
            .its('body.carteira.id')
            .should('eq', carteiraB?.id)

          // Cliente tenta definir o vínculo por conta própria: nada disso pode ter sucesso.
          const tentativas = [
            { method: 'PATCH', url: '/auth/me', body: { carteiraId: carteiraA?.id } },
            { method: 'PATCH', url: `/usuarios/${conta.id}`, body: { carteiraId: carteiraA?.id } },
            {
              method: 'PUT',
              url: `/usuarios/${conta.id}/carteira`,
              body: { carteiraId: carteiraA?.id },
            },
          ]
          for (const tentativa of tentativas) {
            cy.apiRequest({ ...tentativa, failOnStatusCode: false })
              .its('status', { log: false })
              .should('be.oneOf', NAO_SUCESSO)
          }
          vinculoAtual().should('eq', carteiraB?.id)
        })
      })
    })
  })

  it('INV 06 · cliente envia o usuarioId de outra pessoa na avaliação → o vínculo da vítima não muda (falha enquanto a rota for pública)', () => {
    cy.criarUsuarioDescartavel().then((vitima) => {
      cy.loginComo(vitima)
      cy.avaliarSuitability(vitima, 'menor').then((avaliacao) => {
        const carteiraDaVitima = avaliacao.carteiraRecomendada?.id

        cy.criarUsuarioDescartavel().then((atacante) => {
          cy.clearCookies()
          cy.loginComo(atacante)
          // Perfil oposto ao da vítima, para que uma gravação indevida mude o vínculo.
          cy.avaliarSuitability(vitima, 'maior').then(() => {
            cy.clearCookies()
            cy.loginComo(vitima)
            vinculoAtual().should('eq', carteiraDaVitima)
          })
        })
      })
    })
  })
})

export {}
